import json
from collections import deque

def fill_enclosed(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seen=[[False]*w for _ in range(h)]
    q=deque()
    for i in range(h):
        for j in (0,w-1):
            if grid[i][j]==0: q.append((i,j)); seen[i][j]=True
    for j in range(w):
        for i in (0,h-1):
            if grid[i][j]==0: q.append((i,j)); seen[i][j]=True
    while q:
        i,j=q.popleft()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and not seen[ni][nj] and grid[ni][nj]==0:
                seen[ni][nj]=True; q.append((ni,nj))
    for i in range(h):
        for j in range(w):
            if grid[i][j]==0 and not seen[i][j]: out[i][j]=8
    return out

