def bbox(comp):
    """The (top, left, bottom, right) bounds of a component's cells."""
    return (min(i for i, j in comp), min(j for i, j in comp),
            max(i for i, j in comp), max(j for i, j in comp))

def fill_rect_interiors(grid, color_fn):
    """Fill the 0-cells inside each color component's bounding box, colored by color_fn(component)."""
